Definition scX_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi ff fp : Z) (errv xa0 : word) (cs1 : list cell) (mx : mem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch ([(S + 256, S + 272)]%Z ++ fr3_XS H ff fp) mx m' /\ wmono bsegs mx m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' S (cs1 ++ [C8 xa0; C8 (Z_to_bv 64 0)]) /\ addressable m' S NEWSZ_SCH
    /\ asc_inv LB m' ioc regb cfgb errv
    /\ as_RHEAP H s LB m'
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
