Lemma sc_exit : forall (s : as_St H) (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (errv : word)
    (gap : list cell) (h32 j472 shb p16 p24 j256 : list byte) (cs1 : list cell) (mx : mem)
    (rax t0 t1 t2 xa0 a1 a2 a3 a4 a5 a6 a7 xs5 xs6 xs7 xs9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32),
  rw_cells bsegs mx spa (sc_loc p16 p24 ff) ->
  rw_cells bsegs mx (spa + 48) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 48) ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (sc_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 32 h32; CB 472 j472; C8 (Z_to_bv 64 fp)] -> rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 64 shb] -> rw_cells bsegs mx fp [C1 (b8 1)] ->
  rw_cells bsegs mx S (cs1 ++ [CB 16 j256]) -> Z.of_nat (cells_size cs1) = 256 -> addressable mx S NEWSZ_SCH ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  asc_inv LB mx ioc regb cfgb errv -> as_RHEAP H s LB mx ->
  as_RFS H ((3, ff, fp) :: LF) mx -> ACONST mx -> stack0 mx lo shi ->
  sc_side H LB LF S ioc regb cfgb lo shi spa ff fp sp tp -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (scX_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF S ioc regb cfgb lo shi ff fp errv xa0 cs1 mx)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) xa0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 S) xs5 xs6 xs7 (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SC_CG6R) fc None mx (seg_rom bsegs)).
